// The icon picker's emoji (M5b §4): a bundled list generated by
// scripts/gen-emoji.ts, loaded when the picker first opens.

/** `[emoji, English name, Spanish name, keywords]`. */
export type EmojiItem = [string, string, string, string];
export interface EmojiGroup {
  id: string;
  items: EmojiItem[];
}

let loaded: Promise<EmojiGroup[]> | null = null;

export function loadEmoji(): Promise<EmojiGroup[]> {
  loaded ??= import('./emoji.json').then((m) => m.default as unknown as EmojiGroup[]);
  return loaded;
}

const fold = (s: string) => s.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();

const haystacks = new WeakMap<EmojiItem, string>();
const haystack = (item: EmojiItem) => {
  let h = haystacks.get(item);
  if (h === undefined) {
    h = fold(`${item[1]} ${item[2]} ${item[3]}`);
    haystacks.set(item, h);
  }
  return h;
};

/** Emoji whose names or keywords hold every word of `query`: those named
 *  exactly that come first, then those whose English or Spanish name holds
 *  the words, then keyword matches. */
export function searchEmoji(groups: EmojiGroup[], query: string): string[] {
  const q = fold(query).trim();
  const words = q.split(/\s+/).filter(Boolean);
  if (!words.length) return [];
  const tiers: string[][] = [[], [], []];
  for (const g of groups) {
    for (const item of g.items) {
      if (!words.every((w) => haystack(item).includes(w))) continue;
      const en = fold(item[1]);
      const es = fold(item[2]);
      const tier = en === q || es === q ? 0 : words.every((w) => `${en} ${es}`.includes(w)) ? 1 : 2;
      tiers[tier].push(item[0]);
    }
  }
  return tiers.flat();
}

/** The name of `emoji` in `lang` ('es' or English), for labels. */
export function emojiName(groups: EmojiGroup[], emoji: string, lang: string): string {
  for (const g of groups) {
    const item = g.items.find((i) => i[0] === emoji);
    if (item) return lang.startsWith('es') ? item[2] : item[1];
  }
  return emoji;
}

const RECENT_KEY = 'nimw.recentIcons';
const MAX_RECENT = 16;

/** Recent picks, newest first (a per-viewer convenience: may be empty). */
export function recentIcons(): string[] {
  try {
    const v: unknown = JSON.parse(localStorage.getItem(RECENT_KEY) ?? '[]');
    return Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : [];
  } catch {
    return [];
  }
}

export function rememberIcon(emoji: string) {
  try {
    const next = [emoji, ...recentIcons().filter((e) => e !== emoji)].slice(0, MAX_RECENT);
    localStorage.setItem(RECENT_KEY, JSON.stringify(next));
  } catch {
    // storage unavailable: no recents
  }
}
